1	import { DUEL_INPUT_LOG_FORMAT, validateDuelInputLog, type DuelInputLog } from "@pirate-sea-race/content/moves";
2	import { hashState } from "../hash.js";
3	import type { DuelInputs } from "./input.js";
4	import type { DuelConfig, DuelState } from "./state.js";
5	import { stepDuel } from "./step.js";
6	
7	export interface DuelReplay {
8	  readonly state: DuelState;
9	  readonly hash: string;
10	}
11	
12	/** Wraps recorded per-frame inputs, starting from a state at `startFrame`, in the input log format. */
13	export function createDuelInputLog(config: DuelConfig, startFrame: number, inputs: readonly DuelInputs[]): DuelInputLog {
14	  return {
15	    format: DUEL_INPUT_LOG_FORMAT,
16	    version: 1,
17	    movesetVersion: config.moveset.version,
18	    startFrame,
19	    inputs: inputs.map(([a, b]) => [a, b]),
20	  };
21	}
22	
23	/** The part of a log that replays from a state at `frame` (for a restored snapshot). */
24	export function sliceDuelInputLog(log: DuelInputLog, frame: number): DuelInputLog {
25	  if (!Number.isSafeInteger(frame) || frame < log.startFrame || frame > log.startFrame + log.inputs.length) {
26	    throw new RangeError(`frame ${frame} is outside the log (${log.startFrame} to ${log.startFrame + log.inputs.length})`);
27	  }
28	  return { ...log, startFrame: frame, inputs: log.inputs.slice(frame - log.startFrame) };
29	}
30	
31	/** Steps through per-frame inputs and returns every state, the initial one first (for scripted tests and tools). */
32	export function traceDuel(config: DuelConfig, initial: DuelState, inputs: readonly DuelInputs[]): DuelState[] {
33	  const states = [initial];
34	  for (const frameInputs of inputs) states.push(stepDuel(config, states[states.length - 1]!, frameInputs));
35	  return states;
36	}
37	
38	/**
39	 * Runs an input log through the step from `initial` and returns the final state and its hash. Refused when the log
40	 * is malformed, was recorded on other move data, or does not start at the initial state's frame.
41	 */
42	export function replayDuel(config: DuelConfig, initial: DuelState, log: unknown): DuelReplay {
43	  const parsed = validateDuelInputLog(log);
44	  if (!parsed.ok) throw new TypeError(`invalid duel input log: ${parsed.issues.join("; ")}`);
45	  const { movesetVersion, startFrame, inputs } = parsed.value;
46	  const version = config.moveset.version;
47	  if (movesetVersion !== version) throw new Error(`the log was recorded on moveset ${movesetVersion}, not ${version}`);
48	  if (initial.movesetVersion !== version) throw new Error(`the initial state runs on moveset ${initial.movesetVersion}, not ${version}`);
49	  if (initial.frame !== startFrame) throw new Error(`the log starts at frame ${startFrame}, the state is at frame ${initial.frame}`);
50	  let state = initial;
51	  for (const frameInputs of inputs) state = stepDuel(config, state, frameInputs);
52	  return { state, hash: hashState(state) };
53	}
